<?php
namespace App\Services;
use Illuminate\Support\Str;
use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\DB;
use PDO;
use SQLite3;
use ZipArchive;
use RuntimeException;
class CcsReportExport {
 private function root(): string {return app(CcsSqliteBackup::class)->root();}
 private function csv(PDO $pdo,string $sql,string $path,?callable $transform=null): int {
  $stmt=$pdo->query($sql);$headers=[];for($i=0;$i<$stmt->columnCount();$i++)$headers[]=$stmt->getColumnMeta($i)['name'];
  if($transform)$headers=array_keys($transform(array_fill_keys($headers,null)));
  $out=fopen($path,'xb');if(!$out)throw new RuntimeException('Cannot write report.');$count=0;
  try{fwrite($out,"\xEF\xBB\xBF");fputcsv($out,$headers,',','"','',"\r\n");while($row=$stmt->fetch(PDO::FETCH_ASSOC)){if($transform)$row=$transform($row);foreach($row as &$value){if(is_string($value)&&preg_match('/^[\s]*[=+\-@]/u',$value))$value="'".$value;}unset($value);if(fputcsv($out,array_values($row),',','"','',"\r\n")===false)throw new RuntimeException('Could not finish CSV export.');$count++;}}finally{fclose($out);$stmt->closeCursor();}return $count;
 }
 public function create(int $actorId): array {
  if(!class_exists(SQLite3::class)||!class_exists(ZipArchive::class))throw new RuntimeException('PHP sqlite3 and zip extensions are required.');$live=app(CcsSqliteBackup::class)->database();$id=(string)Str::uuid();$stamp=Carbon::now('Asia/Colombo')->format('Y-m-d_H-i-s');$folder='Reports_'.$stamp;$dir=$this->root().'/reports-'.$id;if(!mkdir($dir,0700))throw new RuntimeException('Cannot create report export folder.');mkdir($dir.'/'.$folder,0700);$snapshot=$dir.'/snapshot.sqlite';$archive=$dir.'/reports.zip';$files=[];$pdo=null;
  try{
   $source=new SQLite3($live,SQLITE3_OPEN_READONLY);$destination=new SQLite3($snapshot,SQLITE3_OPEN_READWRITE|SQLITE3_OPEN_CREATE);$source->busyTimeout(5000);try{if(!$source->backup($destination))throw new RuntimeException('Could not take a report snapshot.');}finally{$destination->close();$source->close();}
   $pdo=new PDO('sqlite:'.$snapshot,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$pdo->exec('PRAGMA trusted_schema=OFF');$pdo->exec('PRAGMA query_only=ON');if($pdo->query('PRAGMA integrity_check')->fetchAll(PDO::FETCH_COLUMN)!==['ok'])throw new RuntimeException('Report snapshot integrity check failed.');
   $parents=" FROM invoices i JOIN repair_jobs j ON j.id=i.repair_job_id JOIN vehicles v ON v.id=j.vehicle_id JOIN customers c ON c.id=v.customer_id WHERE i.status IN ('issued','partially_paid','paid') AND j.deleted_at IS NULL AND v.deleted_at IS NULL AND c.deleted_at IS NULL";
   $paid="ROUND(COALESCE((SELECT SUM(p.amount_lkr) FROM payments p WHERE p.invoice_id=i.id),0),2)";
   $sales="SELECT i.id AS invoice_id,i.invoice_number,i.issued_at,i.created_at,j.job_number,c.customer_code,c.name AS customer,c.phone,v.registration_number,i.status,i.subtotal_lkr,i.discount_lkr,i.total_lkr,$paid AS paid_lkr,MAX(0,ROUND(i.total_lkr-$paid,2)) AS outstanding_lkr".$parents;
   $queries=[
    'sales_all_dates.csv'=>$sales.' ORDER BY i.issued_at,i.id',
    'outstanding_dues.csv'=>"SELECT * FROM ($sales) s WHERE s.outstanding_lkr>0 ORDER BY s.outstanding_lkr DESC",
    'daily_sales_summary.csv'=>"SELECT DATE(COALESCE(issued_at,created_at)) AS sale_date_as_stored,COUNT(*) AS invoices,ROUND(SUM(total_lkr),2) AS sales_lkr,ROUND(SUM(paid_lkr),2) AS received_to_date_lkr,ROUND(SUM(outstanding_lkr),2) AS outstanding_to_date_lkr FROM ($sales) s GROUP BY DATE(COALESCE(issued_at,created_at)) ORDER BY sale_date_as_stored",
    'monthly_sales_summary.csv'=>"SELECT SUBSTR(COALESCE(issued_at,created_at),1,7) AS month_as_stored,COUNT(*) AS invoices,ROUND(SUM(total_lkr),2) AS sales_lkr,ROUND(SUM(paid_lkr),2) AS received_to_date_lkr,ROUND(SUM(outstanding_lkr),2) AS outstanding_to_date_lkr FROM ($sales) s GROUP BY SUBSTR(COALESCE(issued_at,created_at),1,7) ORDER BY month_as_stored",
    'payment_history_all_dates.csv'=>"SELECT p.id,p.paid_at,i.invoice_number,j.job_number,c.name AS customer,v.registration_number,p.amount_lkr,p.method,p.reference,u.name AS received_by FROM payments p JOIN invoices i ON i.id=p.invoice_id JOIN repair_jobs j ON j.id=i.repair_job_id JOIN vehicles v ON v.id=j.vehicle_id JOIN customers c ON c.id=v.customer_id LEFT JOIN users u ON u.id=p.received_by_user_id WHERE i.status IN ('issued','partially_paid','paid') AND j.deleted_at IS NULL AND v.deleted_at IS NULL AND c.deleted_at IS NULL ORDER BY p.paid_at,p.id",
    'daily_payment_summary.csv'=>"SELECT DATE(p.paid_at) AS payment_date_as_stored,COUNT(*) AS receipts,ROUND(SUM(p.amount_lkr),2) AS received_lkr FROM payments p JOIN invoices i ON i.id=p.invoice_id JOIN repair_jobs j ON j.id=i.repair_job_id JOIN vehicles v ON v.id=j.vehicle_id JOIN customers c ON c.id=v.customer_id WHERE i.status IN ('issued','partially_paid','paid') AND j.deleted_at IS NULL AND v.deleted_at IS NULL AND c.deleted_at IS NULL GROUP BY DATE(p.paid_at) ORDER BY payment_date_as_stored",
    'stock_current.csv'=>'SELECT id,sku,name,category,service_application,condition,item_year,supplier,quantity_on_hand,reorder_level,purchase_price_lkr,selling_price_lkr,has_serial,is_battery_module,default_warranty_rule_id,active,created_at,updated_at FROM inventory_items ORDER BY name',
    'staff_directory.csv'=>'SELECT id,name,email,ccs_role,ccs_active,created_at,updated_at FROM users ORDER BY name',
    'audit_log.csv'=>'SELECT a.id,a.created_at,u.name AS staff,a.action,a.entity_type,a.entity_id FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id',
   ];
   foreach(['customers','vehicles','repair_jobs','invoices','invoice_items','payments','stock_units','stock_movements','battery_service_records','battery_module_readings','warranty_rules','warranty_claims','warranty_service_visits'] as $table)$queries[$table.'_all_records.csv']='SELECT * FROM "'.$table.'" ORDER BY id';
   foreach($queries as $name=>$query){$path=$dir.'/'.$folder.'/'.$name;$rows=$this->csv($pdo,$query,$path);$files[]=['name'=>$name,'rows'=>$rows];}
   $name='warranty_cards.csv';$rows=$this->csv($pdo,"SELECT w.*,j.job_number,c.name AS customer,v.registration_number,(SELECT COUNT(*) FROM warranty_service_visits sv WHERE sv.warranty_id=w.id) AS services_used FROM warranties w JOIN repair_jobs j ON j.id=w.repair_job_id JOIN vehicles v ON v.id=j.vehicle_id JOIN customers c ON c.id=v.customer_id ORDER BY w.id",$dir.'/'.$folder.'/'.$name,function($row){$s=json_decode((string)($row['terms_snapshot']??''),true)??[];unset($row['terms_snapshot']);$row['package']=$s['name']??'';$row['serial']=$s['covered_serial']??'';$row['covered_description']=$s['covered_description']??'';$row['months']=$s['duration_months']??'';$row['distance_km']=$s['distance_km']??'';$row['free_services_included']=$s['free_service_count']??0;$row['terms']=$s['terms']??'';$row['provisional']=($s['provisional']??true)?1:0;return $row;});$files[]=['name'=>$name,'rows'=>$rows];
   $readme="CCS Reports\r\nGenerated (Asia/Colombo): ".$stamp."\r\nAll dates through the database snapshot. Currency: LKR.\r\n\r\nExtract this ZIP before opening CSV files in Excel, LibreOffice or a text editor. CSV files use UTF-8 with BOM. Import serials/codes/phone numbers as TEXT to preserve leading zeros. Text beginning with spreadsheet formula characters has a leading apostrophe for safety.\r\n\r\nSales/payment summaries exclude draft/void invoices and archived parent records. Received-to-date is all saved receipts against those invoices, not receipts collected on the sale date. Daily payment summary shows actual receipt dates. Date/time values are exported as stored; no historic timezone is guessed.\r\n\r\n*_all_records.csv includes all rows, including drafts/void/archived history where present. These are data reports, not net-sales totals. Never sum invoice totals after joining line items. Warranty CSV includes pending/provisional records flagged; dates do not decide claim eligibility.\r\n\r\nStaff report omits password hashes/tokens. Audit report omits private metadata. Full database restore uses a separate CCS backup ZIP from Backup & Restore, not this reports ZIP. Reports contain private customer/business information.\r\n\r\nFiles / data rows:\r\n";foreach($files as $file)$readme.=$file['name'].' : '.$file['rows']."\r\n";file_put_contents($dir.'/'.$folder.'/README.txt',$readme);
   $pdo=null;unlink($snapshot);$zip=new ZipArchive();if($zip->open($archive,ZipArchive::CREATE|ZipArchive::EXCL)!==true)throw new RuntimeException('Cannot create reports ZIP.');foreach(glob($dir.'/'.$folder.'/*') as $file){$entry=$folder.'/'.basename($file);if(!$zip->addFile($file,$entry)||!$zip->setCompressionName($entry,ZipArchive::CM_STORE))throw new RuntimeException('Could not add report to ZIP.');}if(!$zip->close())throw new RuntimeException('Cannot finish reports ZIP.');clearstatcache(true,$archive);
   $check=new ZipArchive();if($check->open($archive,ZipArchive::CHECKCONS)!==true)throw new RuntimeException('Report ZIP integrity check failed.');try{for($i=0;$i<$check->numFiles;$i++){$entry=$check->getNameIndex($i);$stream=$check->getStream($entry);if(!$stream)throw new RuntimeException('Cannot read report ZIP entry.');$hash=hash_init('sha256');try{$bytes=hash_update_stream($hash,$stream);}finally{fclose($stream);}if($bytes!==filesize($dir.'/'.$entry)||!hash_equals(hash_file('sha256',$dir.'/'.$entry),hash_final($hash)))throw new RuntimeException('Report ZIP checksum failed.');}}finally{$check->close();}
   $meta=['id'=>$id,'filename'=>'CCS_Reports_'.$stamp.'_'.substr($id,0,8).'.zip','created_at'=>gmdate('c'),'bytes'=>filesize($archive),'sha256'=>hash_file('sha256',$archive),'files'=>count($files),'folder'=>$folder];file_put_contents($dir.'/report.json',json_encode($meta,JSON_THROW_ON_ERROR),LOCK_EX);foreach(glob($dir.'/'.$folder.'/*') as $file)unlink($file);rmdir($dir.'/'.$folder);app(CcsAdministration::class)->audit($actorId,'all_reports_exported','report_export',null,['export_id'=>$id,'reports'=>count($files)]);return $meta;
  }catch(\Throwable $e){$pdo=null;@unlink($snapshot);foreach(glob($dir.'/'.$folder.'/*')?:[] as $file)@unlink($file);@rmdir($dir.'/'.$folder);@unlink($archive);@unlink($dir.'/report.json');@rmdir($dir);throw $e;}
 }
 public function listing(): array {$items=[];foreach(glob($this->root().'/reports-*/report.json')?:[] as $file){$m=json_decode(file_get_contents($file),true);if(is_array($m)&&isset($m['id'],$m['created_at'],$m['filename'],$m['bytes']))$items[]=$m;}usort($items,fn($a,$b)=>strcmp($b['created_at'],$a['created_at']));return array_slice($items,0,20);}
 public function file(string $id): array {if(!Str::isUuid($id))throw new RuntimeException('Invalid export ID.');$dir=$this->root().'/reports-'.$id;$meta=json_decode(file_get_contents($dir.'/report.json'),true,512,JSON_THROW_ON_ERROR);$path=$dir.'/reports.zip';clearstatcache(true,$path);if(!is_file($path)||!hash_equals($meta['sha256'],hash_file('sha256',$path)))throw new RuntimeException('Report ZIP checksum failed.');return ['path'=>$path,'meta'=>$meta];}
}
